<?php error_reporting(E_ALL); ini_set('display_errors', '1'); session_start(); require "db.php"; echo "PHP login handler started.<br>"; if ($_SERVER["REQUEST_METHOD"] !== "POST") { echo "This page must be accessed through the login form."; exit; } $username = trim($_POST["username"] ?? ""); $password = $_POST["password"] ?? ""; echo "Username received: " . htmlspecialchars($username) . "<br>"; if ($username === "" || $password === "") { die("Please enter your username and password."); } echo "Looking up user...<br>"; $stmt = $pdo->prepare( "SELECT id, username, password_hash FROM users WHERE username = ? LIMIT 1" ); $stmt->execute([$username]); $user = $stmt->fetch(); if (!$user) { die("User was not found."); } echo "User found.<br>"; if (!password_verify($password, $user["password_hash"])) { die("Password verification failed."); } echo "Password verified successfully!<br>"; session_regenerate_id(true); $_SESSION["user_id"] = $user["id"]; $_SESSION["username"] = $user["username"]; echo "Session created.<br>"; echo "User ID: " . htmlspecialchars($user["id"]) . "<br>"; echo "Username: " . htmlspecialchars($user["username"]) . "<br>"; echo "<br><strong>Login successful!</strong>"; ?>